// build-decks.mjs — (re)generates the self-authored CC0 example decks in this
// folder. Run with `node build-decks.mjs` from this directory.
//
// Why a generator? The `arty.json` deck embeds abstract SVG art as inline
// data: URLs. Authoring those by hand inside JSON is error-prone, so we build
// the SVG strings here and emit them. The other decks are plain enough to spell
// out directly, but we keep them here too so all five decks have a single,
// reproducible, reviewable source of truth.
//
// LICENSE: every byte produced here is authored for edot and dedicated to the
// public domain under CC0 1.0 (see ./LICENSE). The SVG art is generated by this
// script (gradients + geometry only — no fetched assets, no fonts embedded).
//
// The output JSON matches slides-model.js exactly: deck.version/id/title/theme/
// mtime/slides[], each slide {id, layout, background, elements[], notes}. The
// CC0 credit lives in the FIRST slide's `notes` (a top-level `meta` key would be
// dropped by normalizeDeck, but notes round-trip through every codec).

import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const HERE = path.dirname(fileURLToPath(import.meta.url));

// ---------------------------------------------------------------------------
// helpers that mirror the model's element shapes (kept terse + explicit)
// ---------------------------------------------------------------------------
let _id = 0;
const sid = () => `s-ex-${++_id}`; // stable, human-readable ids for fixtures

// A text element. `runs` is an array of { text, bold?, italic?, level? }.
const text = (role, x, y, w, h, runs) => ({ type: 'text', role, x, y, w, h, runs });
const run = (text, opts = {}) => ({ text, ...opts });
const image = (x, y, w, h, dataUrl, alt) => ({ type: 'image', x, y, w, h, dataUrl, alt });
const shape = (x, y, w, h, s, fill, stroke) => ({ type: 'shape', x, y, w, h, shape: s, fill, stroke });

const slide = (layout, elements, { background = null, notes = '' } = {}) =>
  ({ id: sid(), layout, background, elements, notes });

const deck = (title, theme, slides) =>
  ({ version: 1, id: `deck-ex-${title.toLowerCase().replace(/[^\w]+/g, '-')}`, title, theme, mtime: 0, slides });

const CC0 = (name) =>
  `${name} — a sample deck authored for edot slides. ` +
  'CC0 1.0 / public domain dedication (see third_party/slide-examples/LICENSE). ' +
  'Doubles as an import-fidelity test fixture.';

// ---------------------------------------------------------------------------
// abstract SVG art → data: URL (CC0; generated, not fetched)
// ---------------------------------------------------------------------------
// data: URLs that are *text* (not ;base64) are decoded by slides-formats.js via
// decodeURIComponent, so we URL-encode the raw SVG. Keeping them un-base64'd
// also makes the JSON diff-friendly and human-auditable.
function svgUrl(svg) {
  return 'data:image/svg+xml,' + encodeURIComponent(svg.replace(/\s+/g, ' ').trim());
}

// A full-bleed gradient field with a couple of large geometric accents.
function artGradient(stops, shapes = '', { w = 1600, h = 900 } = {}) {
  const stopXml = stops.map((s, i) =>
    `<stop offset="${(i / (stops.length - 1) * 100).toFixed(0)}%" stop-color="${s}"/>`).join('');
  return svgUrl(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">` +
    `<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1">${stopXml}</linearGradient></defs>` +
    `<rect width="${w}" height="${h}" fill="url(#g)"/>${shapes}</svg>`);
}

const ART_TITLE = artGradient(['#1a1a2e', '#16213e', '#0f3460', '#533483'],
  '<circle cx="1280" cy="220" r="260" fill="#e94560" opacity="0.55"/>' +
  '<circle cx="1340" cy="160" r="120" fill="#ffd460" opacity="0.7"/>');

const ART_WAVE = artGradient(['#0b486b', '#3b8686', '#79bd9a', '#cff09e'],
  '<path d="M0 600 Q400 480 800 600 T1600 600 V900 H0 Z" fill="#0b486b" opacity="0.45"/>' +
  '<path d="M0 700 Q400 580 800 700 T1600 700 V900 H0 Z" fill="#0b486b" opacity="0.65"/>');

const ART_TRIANGLES = artGradient(['#f72585', '#7209b7', '#3a0ca3'],
  '<polygon points="0,0 700,0 0,900" fill="#fff" opacity="0.06"/>' +
  '<polygon points="1600,900 900,900 1600,0" fill="#000" opacity="0.12"/>' +
  '<polygon points="800,250 1050,720 550,720" fill="#ffd460" opacity="0.85"/>');

const ART_GRID = artGradient(['#2b2d42', '#1d1f30'],
  Array.from({ length: 9 }, (_, r) => Array.from({ length: 16 }, (_, c) => {
    const on = (r * 7 + c * 3) % 5 === 0;
    return on ? `<rect x="${c * 100}" y="${r * 100}" width="100" height="100" fill="#8d99ae" opacity="0.18"/>` : '';
  }).join('')).join(''));

const ART_SUN = artGradient(['#ff9a00', '#ff5400', '#7a1f3d'],
  '<circle cx="800" cy="520" r="220" fill="#ffd460"/>' +
  Array.from({ length: 6 }, (_, i) => `<rect x="0" y="${560 + i * 40}" width="1600" height="18" fill="#7a1f3d" opacity="0.55"/>`).join(''));

// ===========================================================================
// 1. corporate.json — deliberately boring, neutral 'ink' theme
// ===========================================================================
const corporate = deck('Quarterly Business Review', 'ink', [
  slide('title', [
    text('title', 0.1, 0.34, 0.8, 0.18, [run('Quarterly Business Review')]),
    text('subtitle', 0.1, 0.54, 0.8, 0.12, [run('Acme Corporation — Q3 FY26')]),
  ], { notes: CC0('Corporate') }),

  slide('title-content', [
    text('title', 0.06, 0.06, 0.88, 0.16, [run('Agenda')]),
    text('body', 0.06, 0.26, 0.88, 0.66, [
      run('Executive summary'),
      run('Financial highlights'),
      run('Operational metrics'),
      run('Strategic initiatives'),
      run('Q&A'),
    ]),
  ]),

  slide('title-content', [
    text('title', 0.06, 0.06, 0.88, 0.16, [run('Executive Summary')]),
    text('body', 0.06, 0.26, 0.88, 0.66, [
      run('Revenue grew 12% year over year', { bold: true }),
      run('Driven by enterprise segment expansion', { level: 1 }),
      run('And improved customer retention', { level: 1 }),
      run('Operating margin held steady at 18%'),
      run('Headcount up 4% with focus on engineering'),
    ]),
  ]),

  slide('two-column', [
    text('title', 0.06, 0.06, 0.88, 0.14, [run('Strengths vs. Risks')]),
    text('body', 0.06, 0.24, 0.43, 0.68, [
      run('Strengths', { bold: true }),
      run('Strong recurring revenue base'),
      run('Healthy pipeline coverage'),
      run('Low customer concentration'),
    ]),
    text('body2', 0.51, 0.24, 0.43, 0.68, [
      run('Risks', { bold: true }),
      run('FX headwinds in EMEA'),
      run('Hiring competition for senior roles'),
      run('Supply lead-time variability'),
    ]),
  ]),

  slide('section', [
    text('title', 0.08, 0.42, 0.84, 0.18, [run('Thank you')]),
  ], { notes: 'Close with contact details and next review date.' }),
]);

// ===========================================================================
// 2. arty.json — Keynote-style, image-forward, big type, 'midnight' theme
// ===========================================================================
const arty = deck('Design as Atmosphere', 'midnight', [
  slide('blank', [
    image(0, 0, 1, 1, ART_TITLE, 'Abstract gradient with glowing circles'),
    text('title', 0.08, 0.40, 0.84, 0.22, [run('DESIGN AS ATMOSPHERE')]),
    text('subtitle', 0.08, 0.64, 0.7, 0.1, [run('a visual essay')]),
  ], { background: '#0f0f1a', notes: CC0('Arty') + ' All backgrounds are generated SVG (CC0).' }),

  slide('blank', [
    image(0, 0, 1, 1, ART_WAVE, 'Layered wave forms in teal and green'),
    text('title', 0.08, 0.12, 0.84, 0.2, [run('FLOW')]),
  ], { background: '#0b486b' }),

  slide('blank', [
    image(0, 0, 1, 1, ART_TRIANGLES, 'Magenta-to-indigo gradient with a gold triangle'),
    text('title', 0.5, 0.66, 0.44, 0.22, [run('TENSION')]),
  ], { background: '#3a0ca3' }),

  slide('blank', [
    image(0, 0, 1, 1, ART_GRID, 'Scattered translucent squares on a dark grid'),
    text('title', 0.08, 0.40, 0.84, 0.2, [run('SYSTEM')]),
    text('subtitle', 0.08, 0.62, 0.6, 0.1, [run('order from repetition')]),
  ], { background: '#1d1f30' }),

  slide('blank', [
    image(0, 0, 1, 1, ART_SUN, 'A gold sun over horizontal bands at dusk'),
    text('title', 0.08, 0.10, 0.84, 0.2, [run('WARMTH')]),
  ], { background: '#7a1f3d' }),

  slide('title', [
    text('title', 0.1, 0.36, 0.8, 0.2, [run('Thank you.')]),
    text('subtitle', 0.1, 0.58, 0.8, 0.1, [run('— made with edot slides')]),
  ], { background: '#13151c' }),
]);

// ===========================================================================
// 3. equations.json — Unicode math, 'paper' theme
// ===========================================================================
const equations = deck('A Tour of Famous Equations', 'paper', [
  slide('title', [
    text('title', 0.1, 0.34, 0.8, 0.18, [run('A Tour of Famous Equations')]),
    text('subtitle', 0.1, 0.54, 0.8, 0.12, [run('rendered as Unicode mathematics')]),
  ], {
    notes: CC0('Equations') + '\n\n' +
      'NOTE ON FIDELITY: real PowerPoint equations use OMML (Office Math Markup ' +
      'Language) inside a:txBody. The edot PPTX exporter does NOT emit OMML — it ' +
      'has no math run support. This deck therefore represents every formula as ' +
      'plain Unicode text (∑ ∫ √ ∂ ∇, Greek letters, super/subscripts, unicode ' +
      'fractions), which round-trips losslessly as text but will not become a ' +
      'native equation object in PowerPoint.',
  }),

  slide('title-content', [
    text('title', 0.06, 0.06, 0.88, 0.16, [run('Euler’s identity')]),
    text('body', 0.06, 0.26, 0.88, 0.66, [
      run('e^(iπ) + 1 = 0', { bold: true }),
      run('relating e, i, π, 1 and 0', { italic: true, level: 1 }),
    ]),
  ]),

  slide('title-content', [
    text('title', 0.06, 0.06, 0.88, 0.16, [run('Mass–energy equivalence')]),
    text('body', 0.06, 0.26, 0.88, 0.66, [
      run('E = mc²', { bold: true }),
      run('E = energy, m = mass, c = speed of light', { level: 1 }),
    ]),
  ]),

  slide('title-content', [
    text('title', 0.06, 0.06, 0.88, 0.16, [run('The Gaussian integral')]),
    text('body', 0.06, 0.26, 0.88, 0.66, [
      run('∫₋∞^∞ e^(−x²) dx = √π', { bold: true }),
      run('a definite integral over the whole real line', { level: 1 }),
    ]),
  ]),

  slide('title-content', [
    text('title', 0.06, 0.06, 0.88, 0.16, [run('Maxwell — Gauss’s law')]),
    text('body', 0.06, 0.26, 0.88, 0.66, [
      run('∇ · E = ρ / ε₀', { bold: true }),
      run('divergence of the electric field', { level: 1 }),
      run('∇ × B − μ₀ε₀ ∂E/∂t = μ₀J', { bold: true }),
      run('Ampère’s law with Maxwell’s correction', { level: 1 }),
    ]),
  ]),

  slide('title-content', [
    text('title', 0.06, 0.06, 0.88, 0.16, [run('The basics, in symbols')]),
    text('body', 0.06, 0.26, 0.88, 0.66, [
      run('Summation:  ∑ᵢ₌₁ⁿ i = n(n+1) / 2'),
      run('Limit:  lim_(x→0) (sin x) / x = 1'),
      run('Fraction (unicode):  ½ + ⅓ + ¼ = 13⁄12'),
      run('Greek:  α β γ δ θ λ μ π σ φ ω  Δ Σ Ω ∂ ∇ ∞'),
    ]),
  ]),
]);

// ===========================================================================
// 4. multilingual-rtl.json — L2R + RTL (+ CJK) in the same slides, 'classic'
// ===========================================================================
const multilingual = deck('Multilingual & Bidirectional', 'classic', [
  slide('title', [
    text('title', 0.1, 0.34, 0.8, 0.18, [run('Hello · مرحبا · שלום · 你好')]),
    text('subtitle', 0.1, 0.54, 0.8, 0.12, [run('a left-to-right and right-to-left mix')]),
  ], { notes: CC0('Multilingual-RTL') + ' A real bidi rendering test fixture.' }),

  slide('title-content', [
    text('title', 0.06, 0.06, 0.88, 0.16, [run('Greetings around the world')]),
    text('body', 0.06, 0.26, 0.88, 0.66, [
      run('English: Welcome to the presentation'),
      run('العربية: مرحبًا بكم في العرض التقديمي'),
      run('עברית: ברוכים הבאים למצגת'),
      run('中文: 欢迎来到演示文稿'),
      run('Mixed in one line: total = المجموع = סך הכול = 42'),
    ]),
  ]),

  slide('two-column', [
    text('title', 0.06, 0.06, 0.88, 0.14, [run('English ⇄ Arabic')]),
    text('body', 0.06, 0.24, 0.43, 0.68, [
      run('English', { bold: true }),
      run('Book'),
      run('Peace'),
      run('Knowledge'),
      run('Water'),
    ]),
    text('body2', 0.51, 0.24, 0.43, 0.68, [
      run('العربية', { bold: true }),
      run('كتاب'),
      run('سلام'),
      run('معرفة'),
      run('ماء'),
    ]),
  ]),

  slide('two-column', [
    text('title', 0.06, 0.06, 0.88, 0.14, [run('English ⇄ Hebrew')]),
    text('body', 0.06, 0.24, 0.43, 0.68, [
      run('English', { bold: true }),
      run('Book'),
      run('Peace'),
      run('Friend'),
      run('Light'),
    ]),
    text('body2', 0.51, 0.24, 0.43, 0.68, [
      run('עברית', { bold: true }),
      run('ספר'),
      run('שלום'),
      run('חבר'),
      run('אור'),
    ]),
  ]),

  slide('title-content', [
    text('title', 0.06, 0.06, 0.88, 0.16, [run('CJK: 中文 · 日本語 · 한국어')]),
    text('body', 0.06, 0.26, 0.88, 0.66, [
      run('中文 (Chinese): 这是一个多语言的幻灯片演示。'),
      run('日本語 (Japanese): これは多言語のスライドです。'),
      run('한국어 (Korean): 이것은 다국어 슬라이드입니다.'),
      run('Bidi punctuation test: (سلام) [שלום] {你好}'),
    ]),
  ]),
]);

// ===========================================================================
// 5. torture.json — edge cases + nav stress (15+ slides), 'midnight'
// ===========================================================================
const LONG = 'This is a deliberately very long bullet point intended to overflow ' +
  'the body text box and test wrapping, clipping, and layout robustness when an ' +
  'author pastes a whole paragraph into a single bullet instead of breaking it ' +
  'into digestible lines, which of course never happens in real presentations.';

const tortureSlides = [
  slide('title', [
    text('title', 0.1, 0.34, 0.8, 0.18, [run('Torture Test 🔥')]),
    text('subtitle', 0.1, 0.54, 0.8, 0.12, [run('edge cases & navigation stress')]),
  ], { notes: CC0('Torture') }),

  slide('title-content', [
    text('title', 0.06, 0.06, 0.88, 0.16, [run('Very long bullets')]),
    text('body', 0.06, 0.26, 0.88, 0.66, [run(LONG), run(LONG + ' ' + LONG)]),
  ]),

  slide('title-content', [
    text('title', 0.06, 0.06, 0.88, 0.16, [run('Five indent levels')]),
    text('body', 0.06, 0.26, 0.88, 0.66, [
      run('Level 0', { level: 0 }),
      run('Level 1', { level: 1 }),
      run('Level 2', { level: 2 }),
      run('Level 3', { level: 3 }),
      run('Level 4', { level: 4 }),
    ]),
  ]),

  slide('title-content', [
    text('title', 0.06, 0.06, 0.88, 0.16, [run('Special characters & emoji')]),
    text('body', 0.06, 0.26, 0.88, 0.66, [
      run('XML-hostile: < > & " \' </a:t> <script>'),
      run('Emoji: 🐥🔥🎉🦄🌍🧪✅❌📊🚀'),
      run('Combining/marks: café · naïve · Zürich · señor'),
      run('Whitespace   gaps   and	tabs	preserved'),
      run('Zero-width & quotes: “smart” ‘quotes’ — em–dash …'),
    ]),
  ]),

  // Empty slide (blank layout, no elements) — normalizeDeck keeps it as-is.
  slide('blank', [], { notes: 'This slide is intentionally empty.' }),

  // Image-only slide (a tiny generated SVG so there is no fetched asset).
  slide('blank', [
    image(0.25, 0.2, 0.5, 0.6, ART_TITLE, 'Image-only slide'),
  ], { notes: 'This slide has only an image, no text.' }),

  slide('title-content', [
    text('title', 0.06, 0.06, 0.88, 0.16, [run('Bold + italic mix')]),
    text('body', 0.06, 0.26, 0.88, 0.66, [
      run('Plain line'),
      run('Bold line', { bold: true }),
      run('Italic line', { italic: true }),
      run('Bold AND italic', { bold: true, italic: true }),
    ]),
  ]),

  slide('two-column', [
    text('title', 0.06, 0.06, 0.88, 0.14, [run('Two columns, uneven')]),
    text('body', 0.06, 0.24, 0.43, 0.68, [run('Just one point on the left.')]),
    text('body2', 0.51, 0.24, 0.43, 0.68, [
      run('Many'), run('points'), run('on'), run('the'), run('right'), run('side'), run('here'),
    ]),
  ]),

  slide('section', [text('title', 0.08, 0.42, 0.84, 0.18, [run('— Section break —')])]),
];

// pad out to 16 slides for navigation stress.
for (let i = tortureSlides.length; i < 16; i++) {
  tortureSlides.push(slide('title-content', [
    text('title', 0.06, 0.06, 0.88, 0.16, [run(`Filler slide ${i + 1}`)]),
    text('body', 0.06, 0.26, 0.88, 0.66, [run(`Navigation stress slide number ${i + 1}.`)]),
  ]));
}

const torture = deck('Torture Test', 'midnight', tortureSlides);

// ---------------------------------------------------------------------------
// emit
// ---------------------------------------------------------------------------
const decks = { corporate, arty, equations, 'multilingual-rtl': multilingual, torture };
for (const [name, d] of Object.entries(decks)) {
  // reset per-deck id counter so ids are stable across runs.
  writeFileSync(path.join(HERE, `${name}.json`), JSON.stringify(d, null, 2) + '\n');
  console.log(`wrote ${name}.json (${d.slides.length} slides)`);
}
